68	
69	/**
70	 * @author Vitaliy Fedoriv
71	 */
72	
73	@RestController
74	@CrossOrigin(exposedHeaders = "errors, content-type")
75	@RequestMapping("/api")
76	public class OwnerRestControllerV1 implements OwnersApi {
77	
78	    /**
79	     * Dedicated audit logger. A single line is emitted here on each successful owner create,
80	     * carrying the new owner's id, customer code and registration date.
81	     */
82	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
83	
84	    /**
85	     * Maximum number of owners a single city may hold. A create whose city already contains this many
86	     * owners is rejected with a {@code 409 Conflict} (see {@link #rejectCityAtCapacity}).
87	     */
88	    private static final int MAX_OWNERS_PER_CITY = 50;
89	
90	    /**
91	     * Maximum number of owners that may be registered in a single day. A create made once this many
92	     * owners already carry today's {@code registrationDate} is rejected with a {@code 429 Too Many
93	     * Requests} (see {@link #rejectDailyRegistrationLimitReached}).
94	     */
95	    private static final int MAX_OWNERS_PER_DAY = 100;
96	
97	    /**
98	     * The number of owners that must already carry a given day's {@code registrationDate} before a
99	     * create made that day is flagged with {@code bulkSignupWarning}. Once more than this many owners
100	     * have already been created for the day, the new owner's {@code bulkSignupWarning} is {@code true}.
101	     */
102	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
103	
104	    /**
105	     * Request header carrying the client-supplied idempotency key for a create. When a create repeats
106	     * with a key already seen, the originally created owner is returned with {@code 200 OK} instead of
107	     * creating a duplicate (see {@link #addOwner}).
108	     */
109	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
110	
111	    /**
112	     * Remembers, per seen {@code Idempotency-Key}, the id of the owner that create originally produced,
113	     * so a repeated create carrying the same key replays that owner rather than creating a duplicate.
114	     */
115	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
116	
117	    private final ClinicService clinicService;
118	
119	    private final OwnerMapper ownerMapper;
120	
121	    private final PetMapper petMapper;
122	
123	    private final VisitMapper visitMapper;
124	
125	    public OwnerRestControllerV1(ClinicService clinicService,
126	                                 OwnerMapper ownerMapper,
127	                                 PetMapper petMapper,
128	                                 VisitMapper visitMapper) {
129	        this.clinicService = clinicService;
130	        this.ownerMapper = ownerMapper;
131	        this.petMapper = petMapper;
132	        this.visitMapper = visitMapper;
133	    }
134	
135	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
136	    @Override
137	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
138	        Collection<Owner> owners;
139	        if (lastName != null) {
140	            owners = this.clinicService.findOwnerByLastName(lastName);
141	        } else {
142	            owners = this.clinicService.findAllOwners();
143	        }
144	        if (owners.isEmpty()) {
145	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
146	        }
147	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
148	    }
149	
150	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
151	    @Override
152	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
153	        Owner owner = this.clinicService.findOwnerById(ownerId);
154	        if (owner == null) {
155	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
156	        }
157	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
158	    }
159	
160	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
161	    @Override
162	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
163	        String idempotencyKey = idempotencyKey();
164	        if (idempotencyKey != null) {
165	            Integer existingId = this.idempotentCreates.get(idempotencyKey);
166	            if (existingId != null) {
167	                Owner existing = this.clinicService.findOwnerById(existingId);
168	                if (existing != null) {
169	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
170	                }
171	            }
172	        }
173	        normalizeAddress(ownerFieldsDto);
174	        rejectBlankOwnerFields(ownerFieldsDto);
175	        rejectInvalidPostcode(ownerFieldsDto);
176	        normalizeTelephone(ownerFieldsDto);
177	        normalizeEmail(ownerFieldsDto);
178	        String householdId = householdIdFor(ownerFieldsDto);
179	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
180	        rejectDuplicateIdentity(ownerFieldsDto);
181	        rejectCityAtCapacity(ownerFieldsDto.getCity());
182	        rejectFutureRegistrationDate(ownerFieldsDto.getRegistrationDate());
183	        LocalDate registrationDate = effectiveRegistrationDate(ownerFieldsDto.getRegistrationDate());
184	        long registeredThatDay = countRegisteredOn(registrationDate);
185	        rejectDailyRegistrationLimitReached(registrationDate, registeredThatDay);
186	        HttpHeaders headers = new HttpHeaders();
187	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
188	        owner.setRegistrationDate(registrationDate);
189	        owner.setHouseholdId(householdId);
190	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
191	        owner.setBulkSignupWarning(registeredThatDay > BULK_SIGNUP_WARNING_THRESHOLD);
192	        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
193	        owner.setMembershipLevel(cappedMembershipLevel(owner));
194	        markPossibleDuplicate(owner, sharesHousehold);
195	        this.clinicService.saveOwner(owner);
196	        if (idempotencyKey != null) {
197	            this.idempotentCreates.put(idempotencyKey, owner.getId());
198	        }
199	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
200	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
201	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
202	            ownerDto.getMembershipLevel(), ownerDto.getMembershipNumber());
203	        headers.setLocation(UriComponentsBuilder.newInstance()
204	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
205	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
206	    }
207	
208	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
209	    @Override
210	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
211	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
212	        if (currentOwner == null) {
213	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
214	        }
215	        normalizeAddress(ownerFieldsDto);
216	        currentOwner.setAddress(addressFor(ownerFieldsDto));
217	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
218	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
219	        currentOwner.setCity(ownerFieldsDto.getCity());
220	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
221	        currentOwner.setLastName(ownerFieldsDto.getLastName());
222	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
223	        normalizeEmail(ownerFieldsDto);
224	        currentOwner.setEmail(ownerFieldsDto.getEmail());
225	        currentOwner.setHouseholdId(householdIdFor(ownerFieldsDto));
226	        this.clinicService.saveOwner(currentOwner);
227	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
228	    }
229	
230	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
231	    @Transactional
232	    @Override
233	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
234	        Owner owner = this.clinicService.findOwnerById(ownerId);
235	        if (owner == null) {
236	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
237	        }
238	        this.clinicService.deleteOwner(owner);
239	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
240	    }
241	
242	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
243	    @Override
244	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
245	        Owner owner = this.clinicService.findOwnerById(ownerId);
246	        if (owner == null) {
247	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
248	        }
249	        HttpHeaders headers = new HttpHeaders();
250	        Pet pet = petMapper.toPet(petFieldsDto);
251	        owner.setId(ownerId);
252	        pet.setOwner(owner);
253	        pet.getType().setName(null);
254	        this.clinicService.savePet(pet);
255	        PetDto petDto = petMapper.toPetDto(pet);
256	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
257	            .buildAndExpand(pet.getId()).toUri());
258	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
259	    }
260	
261	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
262	    @Override
263	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
264	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
265	        if (currentOwner != null) {
266	            Pet currentPet = this.clinicService.findPetById(petId);
267	            if (currentPet != null) {
268	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
269	                currentPet.setName(petFieldsDto.getName());
270	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
271	                this.clinicService.savePet(currentPet);
272	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
273	            }
274	        }
275	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
276	    }
277	
278	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
279	    @Override
280	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
281	        HttpHeaders headers = new HttpHeaders();
282	        Visit visit = visitMapper.toVisit(visitFieldsDto);
283	        Pet pet = new Pet();
284	        pet.setId(petId);
285	        visit.setPet(pet);
286	        this.clinicService.saveVisit(visit);
287	        VisitDto visitDto = visitMapper.toVisitDto(visit);
288	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
289	            .buildAndExpand(visit.getId()).toUri());
290	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
291	    }
292	
293	
294	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
295	    @Override
296	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
297	        Owner owner = this.clinicService.findOwnerById(ownerId);
298	        if (owner != null) {
299	            Pet pet = owner.getPet(petId);
300	            if (pet != null) {
301	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
302	            }
303	        }
304	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
305	    }
306	
307	    /**
308	     * Reads the optional {@code Idempotency-Key} header from the current request. The generated
309	     * {@code addOwner} signature carries only the request body, so the header is pulled from the
310	     * request bound to the current thread. Returns the trimmed key, or {@code null} when the header is
311	     * absent or blank (in which case the create proceeds normally, without idempotent replay).
312	     *
313	     * @return the non-blank idempotency key, or {@code null} when none was supplied
314	     */
315	    private String idempotencyKey() {
316	        if (!(RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes)) {
317	            return null;
318	        }
319	        String key = attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
320	        return isBlank(key) ? null : key.trim();
321	    }
322	
323	    /**
324	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
325	     * {@code telephone} is missing (null) or blank (empty or whitespace only). Bean Validation on
326	     * the request body already rejects null and empty values, but permits whitespace-only strings
327	     * for fields without a stricter pattern (e.g. {@code city}, {@code address}); this guard closes
328	     * that gap so every required field must carry a non-blank value.
329	     *
330	     * @param ownerFieldsDto the submitted owner fields
331	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
332	     */
333	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
334	        List<String> missing = new ArrayList<>();
335	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
336	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
337	        if (isBlank(ownerFieldsDto.getAddressLine1()) && isBlank(ownerFieldsDto.getAddress())) {
338	            missing.add("address");
339	        }
340	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
341	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
342	        if (!missing.isEmpty()) {
343	            throw new InvalidOwnerFieldsException(missing);
344	        }
345	    }
346	
347	    /**
348	     * Rejects an owner whose supplied {@code postcode} is invalid for its {@code city}. The postcode is
349	     * optional: when absent (null) the owner is accepted unchanged, so the request contract stays
350	     * backward-compatible. When present it must be four digits and, when the city maps to a known region,
351	     * must fall within that region's fixed inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
352	     * {@code QLD 4000-4099}); a city with no known region accepts any 4-digit postcode. See
353	     * {@link PostcodeValidator}.
354	     *
355	     * @param ownerFieldsDto the submitted owner fields (its {@code city} is non-blank here,
356	     *                       {@link #rejectBlankOwnerFields} having already run)
357	     * @throws InvalidOwnerFieldsException if a postcode is present but not valid for the city
358	     */
359	    private void rejectInvalidPostcode(OwnerFieldsDto ownerFieldsDto) {
360	        if (!PostcodeValidator.isValid(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode())) {
361	            throw new InvalidOwnerFieldsException(List.of("postcode"));
362	        }
363	    }
364	
365	    private void addIfBlank(List<String> missing, String fieldName, String value) {
366	        if (isBlank(value)) {
367	            missing.add(fieldName);
368	        }
369	    }
370	
371	    private boolean isBlank(String value) {
372	        return value == null || value.isBlank();
373	    }
374	
375	    /**
376	     * Normalizes the submitted address on create to its canonical form (see
377	     * {@link AddressNormalizer#normalize}) and writes it back onto the request so it is the value
378	     * stored and returned, and the form every later address comparison (the required-field check,
379	     * household duplicate detection and the shared household id) is judged on. The structured fields
380	     * are preferred: {@code addressLine1} and the optional {@code addressLine2} are each normalized in
381	     * place, and the flat {@code address} is set to the {@linkplain #composedAddress composed} value
382	     * derived from them when a structured {@code addressLine1} is present, falling back to the
383	     * normalized flat {@code address} otherwise. Any absent field is left absent so
384	     * {@link #rejectBlankOwnerFields} still reports a wholly missing address; a value that is blank
385	     * after normalization likewise reduces to the empty string and is rejected there.
386	     *
387	     * @param ownerFieldsDto the submitted owner fields
388	     */
389	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
390	        String addressLine1 = AddressNormalizer.normalizeOrNull(ownerFieldsDto.getAddressLine1());
391	        String addressLine2 = AddressNormalizer.normalizeOrNull(ownerFieldsDto.getAddressLine2());
392	        String flatAddress = AddressNormalizer.normalizeOrNull(ownerFieldsDto.getAddress());
393	        ownerFieldsDto.setAddressLine1(addressLine1);
394	        ownerFieldsDto.setAddressLine2(addressLine2);
395	        ownerFieldsDto.setAddress(composedAddress(addressLine1, addressLine2, flatAddress));
396	    }
397	
398	    /**
399	     * Composes the flat {@code address} an owner should carry from its (already normalized) address
400	     * fields, preferring the structured form. When a non-blank {@code addressLine1} is present the
401	     * composed address is {@code addressLine1}, with a single space and {@code addressLine2} appended
402	     * when {@code addressLine2} is present; otherwise the flat {@code address} is used unchanged. This
403	     * is the single value every later reader of the address (the required-field check, household
404	     * duplicate detection and the shared household id) is judged on.
405	     *
406	     * @param addressLine1 the normalized first address line, or {@code null}/blank when absent
407	     * @param addressLine2 the normalized second address line, or {@code null}/blank when absent
408	     * @param flatAddress  the normalized flat address, or {@code null}/blank when absent
409	     * @return the composed flat address, or {@code null} when no address form was supplied
410	     */
411	    private String composedAddress(String addressLine1, String addressLine2, String flatAddress) {
412	        if (isBlank(addressLine1)) {
413	            return flatAddress;
414	        }
415	        if (isBlank(addressLine2)) {
416	            return addressLine1;
417	        }
418	        return addressLine1 + " " + addressLine2;
419	    }
420	
421	    /**
422	     * Normalizes the submitted {@code telephone} on create to its canonical form (see
423	     * {@link TelephoneNormalizer#normalize}) and writes it back onto the request so it is the value
424	     * stored and returned. Any input that does not reduce to a valid telephone is rejected with a
425	     * {@code 400 Bad Request}.
426	     *
427	     * @param ownerFieldsDto the submitted owner fields (its {@code telephone} is non-blank here,
428	     *                       {@link #rejectBlankOwnerFields} having already run)
429	     * @throws InvalidOwnerFieldsException if the telephone cannot be normalized to a valid value
430	     */
431	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
432	        String normalized = TelephoneNormalizer.normalize(ownerFieldsDto.getTelephone())
433	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("telephone")));
434	        ownerFieldsDto.setTelephone(normalized);
435	    }
436	
437	    /**
438	     * Normalizes an optionally-supplied {@code email}. When absent (null) or blank the field is left
439	     * untouched (email is optional). When present it is reduced to its canonical form (see
440	     * {@link EmailNormalizer#normalize}) and written back so it is the value stored and returned. Any
441	     * present-but-invalid address is rejected with a {@code 400 Bad Request}.
442	     *
443	     * @param ownerFieldsDto the submitted owner fields
444	     * @throws InvalidOwnerFieldsException if the email is present but not a syntactically valid address,
445	     *                                     or its domain is on the disposable-domain blocklist
446	     */
447	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
448	        String email = ownerFieldsDto.getEmail();
449	        if (email == null || email.isBlank()) {
450	            return;
451	        }
452	        String normalized = EmailNormalizer.normalize(email)
453	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("email")));
454	        if (EmailNormalizer.hasDisposableDomain(normalized)) {
455	            throw new InvalidOwnerFieldsException(List.of("email"));
456	        }
457	        ownerFieldsDto.setEmail(normalized);
458	    }
459	
460	    /**
461	     * Rejects creating an owner whose derived identity collides with an existing owner. All owner
462	     * duplicate detection is now expressed through the single derived {@code identityKey}
463	     * ({@code sha256hex(normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName))}, see
464	     * {@link OwnerIdentity}), which replaces the previously separate telephone, email and household
465	     * checks. Two owners denote the same person when their whole identity keys are equal, so a create
466	     * is rejected as a {@code 409 Conflict} when another (non-deleted) owner already carries the same
467	     * key. Because the telephone is part of the key, two owners who share a last name and postcode but
468	     * carry different telephones have different keys and are both allowed (they are instead recorded as
469	     * a {@linkplain #findPossibleDuplicate possible duplicate}); an email or a household on its own no
470	     * longer makes a duplicate.
471	     *
472	     * @param ownerFieldsDto the submitted owner fields, with telephone and email already normalized
473	     *                       ({@link #normalizeTelephone}, {@link #normalizeEmail})
474	     * @throws DuplicateOwnerIdentityException if another owner already carries the same identity
475	     */
476	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
477	        String identityKey = OwnerIdentity.identityKey(
478	            ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail(), ownerFieldsDto.getLastName());
479	        boolean inUse = activeOwners().stream()
480	            .map(OwnerIdentity::identityKey)
481	            .anyMatch(identityKey::equals);
482	        if (inUse) {
483	            throw new DuplicateOwnerIdentityException(identityKey);
484	        }
485	    }
486	
487	    /**
488	     * The owners considered by duplicate detection: every persisted owner except those flagged
489	     * {@code deleted}. A soft-deleted owner is retained but must never make a later create look like a
490	     * duplicate, so both the hard-duplicate identity check ({@link #rejectDuplicateIdentity}) and the
491	     * soft {@linkplain #findPossibleDuplicate possible-duplicate} match are judged against these owners
492	     * alone. Only owners already persisted (before this create) are included.
493	     *
494	     * @return the non-deleted owners currently persisted
495	     */
496	    private List<Owner> activeOwners() {
497	        return this.clinicService.findAllOwners().stream()
498	            .filter(owner -> !owner.isDeleted())
499	            .toList();
500	    }
501	
502	    /**
503	     * Counts the existing owners (before this create) whose {@code firstName} and {@code lastName}
504	     * both match the submitted values, compared case-insensitively. The count reflects only owners
505	     * already persisted at the time of the create, so the owner being created is never included.
506	     *
507	     * @param firstName the submitted first name (non-blank here, {@link #rejectBlankOwnerFields}
508	     *                  having already run)
509	     * @param lastName  the submitted last name (non-blank here)
510	     * @return the number of existing owners sharing the same first and last name
511	     */
512	    private int countNamesakes(String firstName, String lastName) {
513	        return (int) this.clinicService.findAllOwners().stream()
514	            .filter(owner -> firstName.equalsIgnoreCase(owner.getFirstName())
515	                && lastName.equalsIgnoreCase(owner.getLastName()))
516	            .count();
517	    }
518	
519	    /**
520	     * Counts the existing owners (before this create) belonging to the given household, i.e. those
521	     * whose stored {@code householdId} equals the value derived for the owner being created. The
522	     * count reflects only owners already persisted at the time of the create, so the owner being
523	     * created is never included; callers add one to obtain the household size after this create.
524	     *
525	     * @param householdId the household identifier derived for the owner being created (see
526	     *                    {@link HouseholdNormalizer#toHouseholdId})
527	     * @return the number of existing owners already sharing that household
528	     */
529	    private int countHouseholdMembers(String householdId) {
530	        return householdMembers(householdId).size();
531	    }
532	
533	    /**
534	     * Returns the existing owners (before this create) belonging to the given household, i.e. those
535	     * whose stored {@code householdId} equals the value derived for the owner being created. As with
536	     * {@link #countHouseholdMembers}, only owners already persisted are included, so the owner being
537	     * created is never among them.
538	     *
539	     * @param householdId the household identifier derived for the owner being created (see
540	     *                    {@link HouseholdNormalizer#toHouseholdId})
541	     * @return the existing owners already sharing that household (empty when {@code householdId} is
542	     *         {@code null})
543	     */
544	    private List<Owner> householdMembers(String householdId) {
545	        if (householdId == null) {
546	            return List.of();
547	        }
548	        return this.clinicService.findAllOwners().stream()
549	            .filter(member -> householdId.equals(member.getHouseholdId()))
550	            .toList();
551	    }
552	
553	    /**
554	     * Caps a new owner's {@code membershipLevel} so it cannot exceed one above the current maximum
555	     * {@code membershipLevel} among their existing household members. The owner's own level is the
556	     * value {@linkplain OwnerMapper#membershipLevel(Owner) it would otherwise report}; it is capped at
557	     * {@code maxHouseholdLevel + 1}. When the household has no existing member no cap applies and the
558	     * owner's own level is returned unchanged.
559	     *
560	     * @param owner the owner being created, already stamped with its household id and size
561	     * @return the (possibly capped) membership level to stamp on the owner
562	     */
563	    private int cappedMembershipLevel(Owner owner) {
564	        int ownLevel = this.ownerMapper.membershipLevel(owner);
565	        OptionalInt maxHouseholdLevel = householdMembers(owner.getHouseholdId()).stream()
566	            .mapToInt(this.ownerMapper::membershipLevel)
567	            .max();
568	        return maxHouseholdLevel.isPresent()
569	            ? Math.min(ownLevel, maxHouseholdLevel.getAsInt() + 1)
570	            : ownLevel;
571	    }
572	
573	    /**
574	     * Derives the address an owner should carry from its submitted fields. The update path stamps an
575	     * owner with an address taken from the request, so routing that through this single method keeps the
576	     * derivation of "the owner's address" in one place, mirroring {@link #householdIdFor} for the
577	     * household id.
578	     *
579	     * @param ownerFieldsDto the submitted owner fields
580	     * @return the address to store on the owner
581	     */
582	    private String addressFor(OwnerFieldsDto ownerFieldsDto) {
583	        return ownerFieldsDto.getAddress();
584	    }
585	
586	    /**
587	     * Derives the household id an owner should carry from its submitted fields (see
588	     * {@link HouseholdNormalizer#toHouseholdId}). Both create and update stamp an owner with a
589	     * household id, so routing them through this single method keeps them agreed on which of the
590	     * owner's fields key the household.
591	     *
592	     * @param ownerFieldsDto the submitted owner fields (its identifying fields are non-blank here,
593	     *                       {@link #rejectBlankOwnerFields} having already run on create)
594	     * @return the owner's household id
595	     */
596	    private String householdIdFor(OwnerFieldsDto ownerFieldsDto) {
597	        return HouseholdNormalizer.toHouseholdId(
598	            ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
599	    }
600	
601	    /**
602	     * Finds an existing owner that the owner being created soft-matches on, or {@code null} when there
603	     * is none. The create has already cleared the hard-duplicate identity check
604	     * ({@link #rejectDuplicateIdentity}), so its {@code identityKey} matches no existing owner; it is a
605	     * <em>possible</em> duplicate when it nevertheless shares an existing owner's {@code postcode} and
606	     * the {@linkplain Soundex#soundex Soundex} of its {@code lastName} while their identity keys still
607	     * differ. Because the telephone is part of the identity key, two owners with the same last name and
608	     * postcode but different telephones have differing keys and so soft-match here rather than colliding
609	     * as a hard duplicate. The oldest such owner (the earliest persisted) is returned so the flag points
610	     * at the original record; owners with no postcode never match, since a shared postcode is required.
611	     *
612	     * @param owner the owner being created, with telephone already normalized and lastName/postcode set
613	     * @return the id of the matching existing owner, or {@code null} when the owner is not a possible
614	     *         duplicate
615	     */
616	    private Integer findPossibleDuplicate(Owner owner) {
617	        String postcode = owner.getPostcode();
618	        if (postcode == null) {
619	            return null;
620	        }
621	        String identityKey = OwnerIdentity.identityKey(owner);
622	        String lastNameCode = Soundex.soundex(owner.getLastName());
623	        return activeOwners().stream()
624	            .filter(existing -> !identityKey.equals(OwnerIdentity.identityKey(existing)))
625	            .filter(existing -> lastNameCode.equals(Soundex.soundex(existing.getLastName())))
626	            .filter(existing -> postcode.equals(existing.getPostcode()))
627	            .map(Owner::getId)
628	            .filter(Objects::nonNull)
629	            .min(Integer::compareTo)
630	            .orElse(null);
631	    }
632	
633	    /**
634	     * Records on the owner being created whether it is a possible (soft) duplicate of an existing
635	     * owner. The match itself is decided by {@link #findPossibleDuplicate}; this method reflects its
636	     * result into the two stored fields, so the interpretation of "is a possible duplicate" lives in
637	     * one place: {@code possibleDuplicateOf} holds the matched owner's id (or {@code null} when there
638	     * is none) and {@code possibleDuplicate} is {@code true} exactly when a match was found. An owner
639	     * that opted in with {@code sharesHousehold} is a declared household member, not a suspected
640	     * duplicate, so it is never flagged.
641	     *
642	     * @param owner           the owner being created, with telephone already normalized and
643	     *                        lastName/postcode set
644	     * @param sharesHousehold whether the request opted in to sharing a household
645	     */
646	    private void markPossibleDuplicate(Owner owner, boolean sharesHousehold) {
647	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicate(owner);
648	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
649	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
650	    }
651	
652	    /**
653	     * Rejects creating an owner whose city already holds {@link #MAX_OWNERS_PER_CITY} or more owners.
654	     * The submitted city is compared case-insensitively against every existing owner's stored city; a
655	     * city that is already at (or over) capacity is reported as a {@code 409 Conflict}.
656	     *
657	     * @param city the submitted city (non-blank here, {@link #rejectBlankOwnerFields} having already
658	     *             run)
659	     * @throws OwnerCityAtCapacityException if the city already contains the maximum number of owners
660	     */
661	    private void rejectCityAtCapacity(String city) {
662	        long ownersInCity = this.clinicService.findAllOwners().stream()
663	            .map(Owner::getCity)
664	            .filter(Objects::nonNull)
665	            .filter(city::equalsIgnoreCase)
666	            .count();
667	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
668	            throw new OwnerCityAtCapacityException(city);
669	        }
670	    }
671	
672	    /**
673	     * Resolves the effective registration date for a create, rolled onto a business day. The
674	     * supplied date is used when present, otherwise the server's current date; either way the result
675	     * is rolled forward to the next Monday when it falls on a Saturday or Sunday (see
676	     * {@link BusinessDayAdjuster#toBusinessDay}). Every value derived from the registration date - the
677	     * stored {@code registrationDate}, the membership number's year segment and the daily
678	     * create-limit's per-day count - is judged on this adjusted date.
679	     *
680	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} to
681	     *                                 default to the server's current date
682	     * @return the effective registration date, guaranteed to fall on a business day
683	     */
684	    /**
685	     * Rejects a create whose supplied {@code registrationDate} lies after the server's current date.
686	     * The raw submitted value is compared against {@link LocalDate#now()} before any business-day
687	     * adjustment; a future date cannot describe a registration that has already happened, so it is
688	     * reported as a {@code 400 Bad Request}. A {@code null} registration date (defaulted to the
689	     * server's current date) and any date on or before today are accepted.
690	     *
691	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} when
692	     *                                 omitted
693	     * @throws InvalidOwnerFieldsException if the supplied date is later than the server's current date
694	     */
695	    private void rejectFutureRegistrationDate(LocalDate suppliedRegistrationDate) {
696	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
697	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
698	        }
699	    }
700	
701	    private LocalDate effectiveRegistrationDate(LocalDate suppliedRegistrationDate) {
702	        LocalDate registrationDate =
703	            suppliedRegistrationDate != null ? suppliedRegistrationDate : LocalDate.now();
704	        return BusinessDayAdjuster.toBusinessDay(registrationDate);
705	    }
706	
707	    /**
708	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
709	     * created for the given business day, judged by their stored {@code registrationDate}. Only owners
710	     * already persisted (before this create) are counted, and only those whose {@code registrationDate}
711	     * equals the adjusted registration date; a day at (or over) that limit is reported as a {@code 429
712	     * Too Many Requests}.
713	     *
714	     * @param registrationDate   the create's effective registration date, already rolled onto a
715	     *                           business day by {@link #effectiveRegistrationDate}
716	     * @param registeredThatDay  the number of owners already persisted (before this create) whose
717	     *                           {@code registrationDate} equals {@code registrationDate}
718	     * @throws OwnerDailyRegistrationLimitException if that day has already reached the maximum number of
719	     *                                              owner registrations
720	     */
721	    private void rejectDailyRegistrationLimitReached(LocalDate registrationDate, long registeredThatDay) {
722	        if (registeredThatDay >= MAX_OWNERS_PER_DAY) {
723	            throw new OwnerDailyRegistrationLimitException(registrationDate);
724	        }
725	    }
726	
727	    /**
728	     * Counts the owners already persisted (before this create) whose stored {@code registrationDate}
729	     * equals the given day. This is the shared per-day accumulation both the daily create-limit and the
730	     * bulk-signup warning are judged on.
731	     *
732	     * @param registrationDate the create's effective registration date, already rolled onto a business
733	     *                         day by {@link #effectiveRegistrationDate}
734	     * @return the number of existing owners registered on that day
735	     */
736	    private long countRegisteredOn(LocalDate registrationDate) {
737	        return this.clinicService.findAllOwners().stream()
738	            .map(Owner::getRegistrationDate)
739	            .filter(registrationDate::equals)
740	            .count();
741	    }
742	}
